pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const dropZone=document.getElementById("drop-zone"),fileInput=document.getElementById("file-input"),loading=document.getElementById("loading"),results=document.getElementById("results"),questionsList=document.getElementById("questions-list"),countLabel=document.getElementById("count-label"),copyBtn=document.getElementById("copy-btn");async function processFile(e){if(e){dropZone.style.display="none",loading.style.display="block";try{const t=await e.arrayBuffer(),n=await pdfjsLib.getDocument(t).promise;let o="";for(let e=1;e<=n.numPages;e++){const t=await n.getPage(e);o+=(await t.getTextContent()).items.map(e=>e.str).join(" ")+" "}extractQuestions(o)}catch(e){alert("Error reading PDF."),location.reload()}}}function extractQuestions(e){loading.style.display="none",results.style.display="block";const t=e.split(/(?<=[.!?])\s+(?=[A-Z0-9])/);let n=[];const o=/^(Q\d+[:.]?|Que \d+[:.]?|\d+[:.)])|(\?)$|^(What|How|Why|Define|Explain|Describe|List|Name|Calculate|State|Discuss)/i;t.forEach(e=>{const t=e.trim();o.test(t)&&t.length>20&&n.push(t)}),0===n.length&&n.push("No explicit questions detected. Try a standard exam paper format."),countLabel.innerText=`Found ${n.length} Questions`,questionsList.innerHTML=n.map((e,t)=>`\n                <div class="question-item">\n                    <span class="q-num">${t+1}</span>\n                    <span>${e}</span>\n\n            `).join(""),copyBtn.onclick=()=>{const e=n.join("\n\n");navigator.clipboard.writeText(e).then(()=>{copyBtn.innerText="Copied! ✅",setTimeout(()=>copyBtn.innerText="Copy All Questions",2e3)})};const s=n.join("\n\n"),i=new Blob([s],{type:"text/plain"}),l=URL.createObjectURL(i),a=document.createElement("a");a.href=l,a.download="extracted_questions.txt",a.click()}dropZone.onclick=()=>fileInput.click(),fileInput.onchange=e=>processFile(e.target.files[0]);